def split_csv(line):
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    i = 0

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote, must be comma or end of line
            if i == n:
                fields.append(''.join(chars))
                return fields
            elif line[i] == ',':
                fields.append(''.join(chars))
                i += 1
                if i == n:
                    fields.append("")
                    return fields
                # else continue loop to parse next field
            else:
                return None
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',' and line[i] != '"':
                i += 1
            if i < n and line[i] == '"':
                return None
            fields.append(line[start:i])
            if i == n:
                return fields
            else:
                # line[i] == ','
                i += 1
                if i == n:
                    fields.append("")
                    return fields
                # else continue loop to parse next field

